/**
 * Minutes lifecycle (ws-a §3.7, §6.3) — pure state machine, no I/O.
 *
 * Flow: meeting close -> auto_drafted (six sec 3.5 fields generated by
 * minutes-draft.ts, never hand-typed) -> NGS edit (supplementaryNotes and
 * corrections ONLY; any attempt to write a generated field* is refused)
 * -> circulated (attendees emailed; due 7 days after the meeting closed)
 * -> approved (by a passed motion at the NEXT meeting of the same body;
 * the approval motion is linked, never text-parsed) -> signed_locked
 * (signedBy + signedAt + retentionUntil = signedAt + 10 years; the signed
 * PDF lives in Drive, its metadata + SHA-256 hash on the record).
 *
 * Signed minutes are never edited and never deleted by any path here.
 * Post-signing corrections are OUT of v1 scope (ws-a §6.3): the signed
 * record stands.
 *
 * The server service (src/lib/server/governance/minutes.ts, sibling/Core
 * integration) persists these transitions; routes never write minutes
 * status directly.
 */

import type { MinutesDraftFields } from "./minutes-draft";
import { isMinutesComplete } from "./minutes-draft";

export const MINUTES_CIRCULATION_WINDOW_MS = 7 * 24 * 60 * 60 * 1000;
export const MINUTES_RETENTION_YEARS = 10;

export type MinutesStatus =
  | "auto_drafted"
  | "in_edit"
  | "circulated"
  | "approved"
  | "signed_locked";

export interface MinutesCorrection {
  field: string;
  note: string;
  by: string;
  at: Date;
}

export interface MinutesPdfMeta {
  driveFileId: string;
  driveLink: string;
  sha256: string;
  fileName: string;
  uploadedAt: Date;
}

/** minutes/{minutesId} lifecycle record (ws-a §3.7) around the six fields. */
export interface MinutesRecord extends MinutesDraftFields {
  id: string;
  meetingId: string;
  bodyId: string;
  status: MinutesStatus;
  generatedAt: Date;
  /** Auto-draft is a system act (ws-a §3.7); the literal value "system". */
  generatedBy: string;
  editedBy: string | null;
  editNotes: string | null;
  /** The ONLY free-text surface on the record besides corrections. */
  supplementaryNotes: string | null;
  corrections: MinutesCorrection[];
  circulatedAt: Date | null;
  /** Meeting closed date + 7 days (Doc 07 sec 3.6: 7 days, calendar). */
  circulationDueAt: Date;
  circulationOverdue: boolean;
  approvedInMeetingId: string | null;
  approvalMotionId: string | null;
  approvedAt: Date | null;
  signedBy: string | null;
  signedAt: Date | null;
  /** signedAt + 10 years, set at signing, immutable afterwards. */
  retentionUntil: Date | null;
  pdf: MinutesPdfMeta | null;
  createdAt: Date;
  updatedAt: Date;
}

export class MinutesError extends Error {
  code: string;
  status: number;
  constructor(code: string, message: string, status = 422) {
    super(message);
    this.name = "MinutesError";
    this.code = code;
    this.status = status;
  }
}

export const MINUTES_TRANSITIONS: Readonly<Record<MinutesStatus, readonly MinutesStatus[]>> = {
  auto_drafted: ["in_edit", "circulated"],
  in_edit: ["circulated"],
  circulated: ["approved"],
  approved: ["signed_locked"],
  signed_locked: [],
};

export function canTransitionMinutes(from: MinutesStatus, to: MinutesStatus): boolean {
  return (MINUTES_TRANSITIONS[from] as readonly string[]).includes(to);
}

export function assertMinutesTransition(from: MinutesStatus, to: MinutesStatus): void {
  if (!canTransitionMinutes(from, to)) {
    throw new MinutesError(
      "invalid_minutes_transition",
      `Minutes cannot move from ${from} to ${to}`,
      409,
    );
  }
}

/** Create the record at meeting close (ws-a §6.3, step 1). */
export function createMinutesRecord(input: {
  id: string;
  meetingId: string;
  bodyId: string;
  fields: MinutesDraftFields;
  meetingClosedAt: Date;
}): MinutesRecord {
  const { id, meetingId, bodyId, fields, meetingClosedAt } = input;
  return {
    id,
    meetingId,
    bodyId,
    status: "auto_drafted",
    ...fields,
    generatedAt: meetingClosedAt,
    generatedBy: "system",
    editedBy: null,
    editNotes: null,
    supplementaryNotes: null,
    corrections: [],
    circulatedAt: null,
    circulationDueAt: new Date(meetingClosedAt.getTime() + MINUTES_CIRCULATION_WINDOW_MS),
    circulationOverdue: false,
    approvedInMeetingId: null,
    approvalMotionId: null,
    approvedAt: null,
    signedBy: null,
    signedAt: null,
    retentionUntil: null,
    pdf: null,
    createdAt: meetingClosedAt,
    updatedAt: meetingClosedAt,
  };
}

const GENERATED_FIELDS: readonly string[] = [
  "fieldAttendees",
  "fieldQuorum",
  "fieldDisclosures",
  "fieldMotions",
  "fieldVoting",
  "fieldConsents",
];

const EDITABLE_FIELDS: readonly string[] = ["supplementaryNotes", "corrections", "editNotes"];

/**
 * The NGS edit (ws-a §4.6 PATCH). Only supplementaryNotes, editNotes and
 * corrections may be patched. A patch carrying any generated field* key is
 * refused with 422 generated_field_immutable even if the value equals the
 * stored one; any other non-editable key is refused as immutable_field.
 * Once signed_locked, every edit is refused with 409 minutes_locked.
 * The first edit of an auto_drafted record moves it to in_edit.
 */
export function applyMinutesEdit(
  record: MinutesRecord,
  patch: Record<string, unknown>,
  editor: { by: string; at: Date },
): MinutesRecord {
  if (record.status === "signed_locked") {
    throw new MinutesError("minutes_locked", "Signed minutes can never be edited", 409);
  }
  for (const key of Object.keys(patch)) {
    if (GENERATED_FIELDS.includes(key)) {
      throw new MinutesError(
        "generated_field_immutable",
        `Minutes field ${key} is generated from records and can never be edited`,
        422,
      );
    }
    if (!EDITABLE_FIELDS.includes(key)) {
      throw new MinutesError(
        "immutable_field",
        `Minutes field ${key} cannot be changed through the edit path`,
        422,
      );
    }
  }
  const next: MinutesRecord = { ...record, editedBy: editor.by, updatedAt: editor.at };
  if (typeof patch.supplementaryNotes === "string" || patch.supplementaryNotes === null) {
    next.supplementaryNotes = patch.supplementaryNotes as string | null;
  }
  if (typeof patch.editNotes === "string" || patch.editNotes === null) {
    next.editNotes = patch.editNotes as string | null;
  }
  if (Array.isArray(patch.corrections)) {
    next.corrections = [...record.corrections, ...(patch.corrections as MinutesCorrection[])];
  }
  if (next.status === "auto_drafted") next.status = "in_edit";
  return next;
}

/** Circulate to attendees (ws-a §4.6). Refused once signed or circulated. */
export function circulateMinutes(record: MinutesRecord, at: Date): MinutesRecord {
  if (record.status === "signed_locked") {
    throw new MinutesError("minutes_locked", "Signed minutes cannot be circulated", 409);
  }
  assertMinutesTransition(record.status, "circulated");
  return { ...record, status: "circulated", circulatedAt: at, updatedAt: at };
}

/**
 * Approval (ws-a §6.3): an ordinary motion at the NEXT meeting of the same
 * body whose create body carried minutesApprovalFor = this minutes id. The
 * caller passes the motion's final status; anything other than a passed
 * close is refused with 422 minutes_not_approved, as is approving minutes
 * that were never circulated.
 */
export function approveMinutes(
  record: MinutesRecord,
  approval: {
    approvalMotionId: string;
    approvedInMeetingId: string;
    approvalMotionStatus: string;
    at: Date;
  },
): MinutesRecord {
  assertMinutesTransition(record.status, "approved");
  if (approval.approvalMotionStatus !== "closed_passed") {
    throw new MinutesError(
      "minutes_not_approved",
      "Minutes can only be approved by a motion that closed passed",
      422,
    );
  }
  return {
    ...record,
    status: "approved",
    approvalMotionId: approval.approvalMotionId,
    approvedInMeetingId: approval.approvedInMeetingId,
    approvedAt: approval.at,
    updatedAt: approval.at,
  };
}

/** signedAt + 10 years (calendar years, ws-a §3.7). Pure. */
export function retentionUntilFor(signedAt: Date): Date {
  const d = new Date(signedAt.getTime());
  d.setUTCFullYear(d.getUTCFullYear() + MINUTES_RETENTION_YEARS);
  return d;
}

/**
 * Sign and lock (ws-a §4.6). Requires status approved with a linked
 * approval motion (422 minutes_not_approved otherwise) and a COMPLETE set
 * of the six generated fields. Sets retentionUntil and the Drive PDF
 * metadata; after this the record is immutable through every path here.
 */
export function signMinutes(
  record: MinutesRecord,
  signing: { signedBy: string; at: Date; pdf: MinutesPdfMeta },
): MinutesRecord {
  if (record.status !== "approved" || !record.approvalMotionId) {
    throw new MinutesError(
      "minutes_not_approved",
      "Minutes must be approved by a passed motion before they can be signed",
      422,
    );
  }
  assertMinutesTransition(record.status, "signed_locked");
  if (!isMinutesComplete(record)) {
    throw new MinutesError(
      "minutes_incomplete",
      "Minutes cannot be signed while any sec 3.5 field is incomplete",
      422,
    );
  }
  return {
    ...record,
    status: "signed_locked",
    signedBy: signing.signedBy,
    signedAt: signing.at,
    retentionUntil: retentionUntilFor(signing.at),
    pdf: signing.pdf,
    updatedAt: signing.at,
  };
}

/**
 * Circulation overdue test (ws-a §6.6 T2): now strictly past
 * circulationDueAt while the record is still auto_drafted or in_edit.
 * Circulated or later records are never overdue, whatever the clock says.
 */
export function isCirculationOverdue(record: MinutesRecord, now: Date): boolean {
  if (record.status !== "auto_drafted" && record.status !== "in_edit") return false;
  return now.getTime() > record.circulationDueAt.getTime();
}
